package com.zhibrary.borrow;
import com.zhibrary.book.*; import com.zhibrary.user.*; import com.zhibrary.waitlist.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.time.temporal.ChronoUnit; import java.util.*;
@RestController @RequestMapping("/api/borrow") @CrossOrigin(origins="http://localhost:5173") public class BorrowController { private final UserRepository users; private final BookRepository books; private final BorrowRepository records; private final WaitlistRepository waitlist; public BorrowController(UserRepository u,BookRepository b,BorrowRepository r,WaitlistRepository w){users=u;books=b;records=r;waitlist=w;} @GetMapping("/{username}") public List<BorrowRecord> history(@PathVariable String username){return records.findByUserUsernameOrderByBorrowedDateDesc(username);} @PostMapping public ResponseEntity<?> borrow(@RequestBody Map<String,String> p){User u=users.findByUsername(p.get("username")).orElseThrow();Book b=books.findById(Long.valueOf(p.get("bookId"))).orElseThrow();List<BorrowRecord> active=records.findByUserUsernameOrderByBorrowedDateDesc(u.getUsername()).stream().filter(x->x.getStatus()==BorrowStatus.ACTIVE).toList();if(active.size()>=3||u.getOutstandingFine()>0||active.stream().anyMatch(x->x.getDueDate().isBefore(LocalDate.now())))return ResponseEntity.badRequest().body(Map.of("message","Borrowing is unavailable while your limit, fine, or overdue status is unresolved."));if(b.getStatus()!=BookStatus.AVAILABLE)return ResponseEntity.badRequest().body(Map.of("message","Book is not available; join the waitlist instead."));b.setStatus(BookStatus.BORROWED);books.save(b);return ResponseEntity.ok(records.save(new BorrowRecord(u,b,LocalDate.now(),LocalDate.now().plusDays(7))));} @PostMapping("/waitlist") public ResponseEntity<?> join(@RequestBody Map<String,String> p){User u=users.findByUsername(p.get("username")).orElseThrow();Book b=books.findById(Long.valueOf(p.get("bookId"))).orElseThrow();if(b.getStatus()==BookStatus.AVAILABLE)return ResponseEntity.badRequest().body(Map.of("message","This book is currently available."));return ResponseEntity.ok(waitlist.save(new WaitlistEntry(u,b)));} @PostMapping("/{id}/return") public BorrowRecord returnBook(@PathVariable Long id){BorrowRecord r=records.findById(id).orElseThrow();long days=Math.max(0,ChronoUnit.DAYS.between(r.getDueDate(),LocalDate.now()));double fine=days*10;r.returnBook(LocalDate.now(),fine);r.getUser().addFine(fine);r.getBook().setStatus(BookStatus.AVAILABLE);books.save(r.getBook());return records.save(r);} }
